// PWA metadata shared by every HTML page through site.js.
(() => {
  const base = new URL('./', document.currentScript.src);
  const link = (rel, path) => {
    let el = document.querySelector('link[rel="' + rel + '"]');
    if (!el) { el = document.createElement('link'); el.rel = rel; document.head.append(el); }
    el.href = new URL(path, base).href;
  };
  link('manifest', 'manifest.json');
  link('apple-touch-icon', 'icon-192.png?v=20261126-small');
  let theme = document.querySelector('meta[name="theme-color"]');
  if (!theme) { theme = document.createElement('meta'); theme.name = 'theme-color'; document.head.append(theme); }
  theme.content = '#087958';
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register(new URL('sw.js', base), {scope: base.pathname, updateViaCache: 'none'})
      .then(() => { document.documentElement.dataset.offline = 'ready'; })
      .catch(() => { document.documentElement.dataset.offline = 'unavailable'; });
  }
})();

