function stop(text=''){session++;reset();if(synth){try{synth.cancel()}catch(e){}}message(text)}
function chunks(text){const result=[],limit=330;for(const raw of text.split(/\n\s*\n/)){const paragraph=raw.replace(/\s+/g,' ').trim();if(!paragraph)continue;if(paragraph.length<=limit){result.push(paragraph);continue}let part='';const flush=()=>{if(part){result.push(part);part=''}};for(const sentence of paragraph.match(/[^.!?۔！？]+[.!?۔！？]*|[.!?۔！？]+/g)||[]){const clean=sentence.trim();if(clean.length<=limit){if(part.length+clean.length+1>limit)flush();part+=(part?' ':'')+clean}else{for(const word of clean.split(/\s+/)){if(word.length>limit){flush();for(let i=0;i<word.length;i+=limit)result.push(word.slice(i,i+limit))}else{if(part.length+word.length+1>limit)flush();part+=(part?' ':'')+word}}}}flush()}return result}
