const secondary=[...header.querySelectorAll('nav a,nav button')];
const sheet=document.createElement('dialog');sheet.className='app-more';sheet.id='app-more';sheet.setAttribute('aria-labelledby','app-more-title');sheet.innerHTML='<div class="app-more-top"><h2 id="app-more-title">Aur dekhein</h2><button type="button" class="ilm-tool" autofocus>Band karein</button></div><div class="app-more-links"></div>';
