const top=document.createElement('div');top.className='app-top';
if(isArticle){const back=document.createElement('button');back.type='button';back.className='app-icon-button';back.setAttribute('aria-label','Peechhe jayein');back.innerHTML=icon('back');back.onclick=()=>{let internal=false;try{const u=new URL(document.referrer);internal=u.origin===location.origin&&u.pathname.startsWith(new URL('./',location.href).pathname)}catch(e){}if(internal&&history.length>1)history.back();else location.href='index.html'};top.append(back)}
