[['home','Home','index.html'],['topics','Topics','index.html#categories'],['search','Talaash','index.html#article-search'],['saved','Pasande','#mere-pasande'],['more','Aur',null]].forEach(([key,label,href])=>{const e=document.createElement(href?'a':'button');if(href)e.href=href;else e.type='button';e.dataset.tab=key;e.innerHTML=icon(key)+'<span>'+label+'</span>';tabs.append(e)});document.body.append(tabs);
