function active(){const hash=location.hash;let current=hash==='#mere-pasande'?'saved':isHome?(hash==='#categories'?'topics':hash==='#article-search'?'search':'home'):isArticle?'topics':'more';tabs.querySelectorAll('[data-tab]').forEach(e=>{if(e.dataset.tab===current)e.setAttribute('aria-current',isHome&&!hash?'page':'location');else e.removeAttribute('aria-current')});if(hash==='#article-search')document.getElementById('article-search')?.focus({preventScroll:true})}
addEventListener('hashchange',active);active();
